import{_ as t,c as s,o as r,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易口诀义","description":"周易口诀义 - 周易口诀义","frontmatter":{"title":"周易口诀义","description":"周易口诀义 - 周易口诀义"},"headers":[],"relativePath":"zh/classics/koujueyi/001.md","filePath":"zh/classics/koujueyi/001.md"}'),o={name:"zh/classics/koujueyi/001.md"};function n(i,a,c,d,p,u){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易口诀义",tabindex:"-1"},[l("周易口诀义 "),e("a",{class:"header-anchor",href:"#周易口诀义","aria-label":"Permalink to “周易口诀义”"},"​")],-1),e("p",null,"钦定四库全书经部一提要易类",-1),e("p",null,"臣 等谨案：",-1),e("p",null,"周易口诀义六卷，唐史征撰。崇文总目曰：「河南史征，不详何代人。」晁公武读书志曰：「田氏以为魏郑公撰，误。」陈振孙曰：「三朝史志有其书，非唐，则五代人避讳作证字。」宋史艺文志又作「史文徽」，盖以「徽」、征二字相近而讹。别本作「史之征」，则又以之、文二字相近而讹耳。今定为史征，从永乐大典；定为唐人，从朱彝尊经义考也。永乐大典载征自序云：「但举宏机，纂其枢要，先以王注为宗，后约孔疏为理。」故崇文总目及晁氏读书志皆以为直抄注疏，以便讲习，考之实不尽然。如乾彖引周氏说，大象引宋衷说，屯彖引李氏说，讼彖引周氏说，师彖引陆绩说，六五引庄氏说，谦六五引张氏说，观大象引郑众说，贲大象引王廙说，颐大象引荀爽说，坎大象引庄氏说，上六引虞氏说，咸大象引何妥说，萃彖引周弘正说，升彖引褚氏说，井大象引何妥说，革彖引宋衷说，鼎彖引何妥说，震九四引郑众说，渐彖引褚氏说，大象引侯果说，困大象引周弘正说，兑大象引郑众说，渐九五引陆绩说。诸家原书，今并亡佚，惟孔疏及李鼎祚周易集解间存其说，是书所引，则多出二家所载之外。又如贲大象所引王氏说，颐大象所引荀爽说，虽属集解所有，而其文互异。坎上六虞翻说，则集解删削过略，此所载独详。盖唐去六朝未远，隋志所载诸家之书犹有存者，故征得以旁搜博引。今阅年数百，旧籍多亡，则遗文绪论，无一非吉光片羽矣。近时惠栋作九经古义，余萧客葺古经解钩沈，于唐以前经义，卑辞只字，搜采至详，而此书所载，均未之及，信为难得之秘本。虽其文义间涉拙滞，傅写亦不免讹脱，而唐以前解易之书，子夏傅既属伪撰，王应麟所辑郑康成注，姚士磷所辑陆绩、干宝二家注，亦非完书。其实存于今者，京房、王弼、孔颖达、李鼎祚四家及此书而五耳。固好古者所宜宝重也。自序作六卷，诸家书目并同。 今仅阙豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦，所佚无多 ，仍编为六卷，存其旧焉。乾隆四十三年二月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅。总校官 臣 陆费墀。",-1)])])}const f=t(o,[["render",n]]);export{_ as __pageData,f as default};
